def tail_width(xs, N):
    """Largest |x_m - x_n| for m, n >= N (one-based) in the list xs."""
    tail = xs[N - 1:]
    return max(tail) - min(tail)

def first_N(xs, eps):
    """Smallest N with tail_width(xs, N) < eps."""
    for N in range(1, len(xs) + 1):
        if tail_width(xs, N) < eps:
            return N
